export function theoremProofHTML(id,math,esc){
 const p=theoremProofs[id];if(!p)return '';
 return '<section class="gt-proof" aria-labelledby="gt-proof-title"><p class="gt-proof-prior">先修知识：'+esc(p.prior)+'</p><h3 id="gt-proof-title">'+esc(p.question)+'</h3><p><strong>要证明的结论：</strong>'+esc(p.claim)+'</p><h4>逐步证明</h4><ol>'+p.steps.map(([title,why,formula])=>'<li><strong>'+esc(title)+'</strong><p>'+esc(why)+'</p>'+(formula?'<div class="gt-proof-formula">'+math(formula)+'</div>':'')+'</li>').join('')+'</ol><div class="gt-proof-application"><h4>现在用下方实验检验推导</h4><p>'+esc(p.application)+'</p></div><p class="gt-proof-caution">'+esc(p.caution)+'</p><details><summary>'+esc(p.challenge)+'</summary><p>'+esc(p.answer)+'</p></details></section>';
}
